insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_153'
from (values
('127.924.d.1.A',3,'A warehouse trainee tells a driver, calmly and with a nod toward the loading board, that his pallets will be ready at Door 6 in ten minutes. She is:','["demonstrating verbal and non-verbal communication consistently in a clear, concise and effective manner", "avoiding the driver", "using vague gestures", "mumbling at the floor"]'::jsonb,0,'Clear communication.','original'),
('127.924.d.1.A',4,'Which statement would best help a driver find the right loading door?','["\"Ask somebody, I''m busy.\"", "\"Your load is at Door 6, to the left of the office.\"", "\"Check around the building.\"", "\"It''s somewhere over there.\""]'::jsonb,1,'Specific directions are clear.','original'),
('127.924.d.1.B',3,'A trainee studies a chart of late deliveries by day, notices Mondays are worst and explains the pattern to her supervisor with the numbers. She is:','["reading numbers aloud with no meaning", "guessing at the cause", "analyzing, interpreting and effectively communicating information, data and observations", "hiding the chart"]'::jsonb,2,'Data communication.','original'),
('127.924.d.1.B',4,'A good report of late-delivery data should include:','["only opinions", "only the raw numbers", "nothing about the source", "what the numbers show and what they likely mean"]'::jsonb,3,'Complete report.','original'),
('127.924.d.1.C',3,'A trainee notices a forklift driver waving his hand and pointing at a blocked aisle and moves the pallet right away. She is:','["observing and interpreting verbal and nonverbal cues to enhance communication", "waiting for a written note", "walking away", "ignoring the driver"]'::jsonb,0,'Nonverbal.','original'),
('127.924.d.1.C',4,'A coworker says he is fine but keeps rubbing his sore wrist and avoiding the lift. A good teammate would:','["say nothing and leave", "ask if he needs help or a break", "assume he is fine", "tell him to lift anyway"]'::jsonb,1,'Read cues.','original'),
('127.924.d.1.D',3,'A trainee takes notes on a dispatcher''s route changes and repeats the new times back to confirm them. She is:','["texting while listening", "assuming the old route", "applying active listening skills to obtain and clarify information", "interrupting the dispatcher"]'::jsonb,2,'Active listening.','original'),
('127.924.d.1.D',4,'Repeating instructions back to the speaker is useful because it:','["hides mistakes", "replaces the instructions", "wastes time", "confirms the message was understood correctly"]'::jsonb,3,'Confirmation.','original'),
('127.924.d.2.A',3,'A trainee sees that scanner errors keep slowing the dock, so she tests the battery, then the Wi-Fi signal, then the label quality and discusses the findings with her team. She is:','["employing critical-thinking skills independently and in groups to solve problems and make decisions", "giving up", "guessing at the cause", "blaming the scanner"]'::jsonb,0,'Critical thinking.','original'),
('127.924.d.2.A',4,'When a team solves a problem together, critical thinking helps by:','["picking the loudest idea", "testing ideas against evidence", "avoiding discussion", "ignoring results"]'::jsonb,1,'Evidence.','original'),
('127.924.d.2.B',3,'A trainee sees the packing station jam every afternoon and maps each step to find where boxes pile up before suggesting a new layout. She is:','["blaming the late shift", "ignoring the jam", "analyzing elements of a problem to develop creative and innovative solutions", "removing the station"]'::jsonb,2,'Innovative solutions.','original'),
('127.924.d.2.B',4,'Mapping each step in a process helps a worker:','["hide inefficiency", "avoid fixing it", "add more steps", "find where the problem begins"]'::jsonb,3,'Map the process.','original'),
('127.924.d.2.C',3,'A trainee correctly uses terms like ''pallet jack'', ''bill of lading'' and ''SKU'' while following a supervisor''s directions. She is:','["demonstrating the use of content, technical concepts and vocabulary when analyzing information and following directions", "guessing at directions", "avoiding the terms", "using wrong names"]'::jsonb,0,'Technical vocabulary.','original'),
('127.924.d.2.C',4,'Why is it important to know the exact meaning of a term on a shipping form?','["It makes the form longer", "A wrong meaning can send the wrong goods to the wrong place", "It has no effect", "Only managers read forms"]'::jsonb,1,'Accurate terms.','original'),
('127.924.d.3.A',3,'A trainee wears her safety shoes, follows the Occupational Safety and Health Administration (OSHA) rules posted on the dock and checks that aisles are clear before moving a load. She is:','["blocking the aisles", "ignoring posted rules", "understanding and consistently following workplace safety rules and regulations", "skipping safety shoes"]'::jsonb,2,'Safety rules.','original'),
('127.924.d.3.A',4,'The Occupational Safety and Health Administration (OSHA) sets standards to:','["lower company costs", "speed up deliveries", "reduce staff", "protect workers from hazards on the job"]'::jsonb,3,'OSHA.','original'),
('127.924.d.3.B',3,'A trainee sees a worker slip on spilled oil, stays with him, alerts her supervisor and helps complete the incident report. She is:','["demonstrating knowledge of procedures for reporting and handling accidents and safety incidents", "hiding the accident", "cleaning up first", "leaving the scene"]'::jsonb,0,'Accident procedures.','original'),
('127.924.d.3.B',4,'After an accident on the dock, the first priority is to:','["start a different task", "get help for anyone who is hurt and keep the area safe", "finish the shipment", "fix the equipment"]'::jsonb,1,'First priority.','original'),
('127.924.d.4.A',3,'A trainee scans every package on her cart, keeps the area neat and asks for more work when her tasks are done. She is:','["waiting for orders", "working slowly", "demonstrating a positive, productive work ethic by performing assigned tasks as directed", "avoiding tasks"]'::jsonb,2,'Work ethic.','original'),
('127.924.d.4.A',4,'What does a productive work ethic look like during a slow hour?','["Hiding in the break room", "Standing idle", "Interrupting busy coworkers", "Finding useful tasks without waiting to be told"]'::jsonb,3,'Productive.','original'),
('127.924.d.4.B',3,'A trainee finds a box with the wrong label and weighs whether to quietly ship it or report it, deciding to report it. She is:','["applying ethical reasoning to make an ethical decision", "guessing", "ignoring the label", "covering up the mistake"]'::jsonb,0,'Ethical reasoning.','original'),
('127.924.d.4.B',4,'Which choice is the most ethical response to a mislabeled package?','["Throw it away", "Report it so it can be corrected", "Ship it anyway", "Relabel it secretly"]'::jsonb,1,'Ethical choice.','original'),
('127.924.d.4.C',3,'A trainee follows the legal limits on how much weight a cart may carry and logs her inspection each shift. She is:','["skipping inspections", "ignoring the limits", "complying with all applicable rules, laws and regulations in a consistent manner", "logging only sometimes"]'::jsonb,2,'Compliance.','original'),
('127.924.d.4.C',4,'Following load-weight regulations is important because they:','["slow the work", "favor managers", "are only suggestions", "help prevent equipment failure and injuries"]'::jsonb,3,'Load regulations.','original'),
('127.924.d.5.A',3,'A trainee in a supervised placement at a distribution center completes a pick-and-pack task, writes down what she did and reviews it with her mentor. She is:','["conducting, documenting and evaluating learning activities in a supervised distribution and logistics experience", "avoiding feedback", "skipping documentation", "working without supervision"]'::jsonb,0,'Supervised learning.','original'),
('127.924.d.5.A',4,'Why should a trainee document her learning activities?','["To avoid feedback", "So she can review progress and identify what to improve", "To replace practice", "To fill empty time"]'::jsonb,1,'Documentation.','original'),
('127.924.d.5.B',3,'A trainee learns to read inventory software reports under her mentor''s guidance to reach the level needed for her chosen job. She is:','["staying with the basics", "changing jobs", "developing advanced technical knowledge and skills related to her occupational objective", "avoiding the software"]'::jsonb,2,'Advanced knowledge.','original'),
('127.924.d.5.B',4,'Advanced skills for a logistics job are best developed through:','["avoiding mentors", "reading only", "watching only", "guided, hands-on practice in a real setting"]'::jsonb,3,'Hands-on.','original'),
('127.924.d.5.C',3,'A trainee''s records show her order accuracy rose from 90 percent to 98 percent over a semester. She is:','["demonstrating growth of technical skill competencies", "showing no change", "losing accuracy", "hiding her records"]'::jsonb,0,'Growth.','original'),
('127.924.d.5.C',4,'Which record best shows skill growth?','["A single day''s notes", "A log with accuracy scores from the start and end of the term", "A list of favorite songs", "An attendance sheet only"]'::jsonb,1,'Show growth.','original'),
('127.924.d.5.D',3,'A trainee compares her checklist to the job requirements and sees she is strong at scanning but weak at route planning. She is:','["praising herself only", "ignoring the checklist", "evaluating strengths and weaknesses in technical skill proficiency", "hiding the weakness"]'::jsonb,2,'Evaluation.','original'),
('127.924.d.5.D',4,'Identifying a weakness is useful when it leads to:','["hiding it from the mentor", "quitting the program", "avoiding the task", "a plan for targeted practice"]'::jsonb,3,'Targeted practice.','original'),
('127.924.d.5.E',3,'A trainee saves a completed shipment log, a photo of a labeled pallet and her supervisor''s note in a folder. She is:','["collecting representative work samples", "discarding records", "copying others'' work", "saving random papers"]'::jsonb,0,'Work samples.','original'),
('127.924.d.5.E',4,'A student is picking items for her logistics portfolio. Which choice is the most representative of her real work?','["A sheet a classmate finished", "A filled-out inventory sheet she completed herself", "A blank template from the internet", "A page she made up for show"]'::jsonb,1,'Samples must be her own typical work.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
